#!/usr/bin/env python3
# scripts/etcd_ha/d333_vault_lente.py — [TERCEROS-VAULT-D333] DEBT-LAB-TERCEROS-DESCARGA-SIN-VERIFICAR-001, lente Vault.
# Uso, desde la raíz del repo:  python3 -I scripts/etcd_ha/d333_vault_lente.py
# Crea provisioning/vault/{VERSION,CLAVE} y scripts/terceros/{vault_instalar.sh,test_vault_instalar.sh} (no pueden
# existir); en el Vagrantfile, VAULT_INSTALL pasa a llamar a vault_instalar.sh; en el Makefile, el target
# test-vault-instalar y su paso del EMECAS tras test-onnxruntime-instalar. Comprueba antes el sha256 de partida de los
# dos ficheros y que cada ancla aparece exactamente las veces esperadas; si algo falla, no escribe nada.
import hashlib, os, pathlib, sys

PARTIDA = {"Vagrantfile": "154672d222b3d70e49ca83b244e040d619c0bfcf127b57fa3784d3ce66f20914", "Makefile": "cc39c385abf0036a3e2214a0b0406bab9d6c5560e42a08d9df8eca13360bf2c8"}
CAMBIOS = {
    "Vagrantfile": [('# ══════════════════════════════════════════════════════════════════════════════\n# VAULT_INSTALL — [VAULT-INSTALL-D312] un único sitio donde se instala Vault, con la versión FIJADA (determinismo de\n# EMECAS: dos up separados por una publicación de HashiCorp no deben dar versiones distintas). Lo usan el defender y la\n# VM etcd. Repo y clave de HashiCorp como hasta DAY311. Versión medida en el defender DAY312: 2.2.1-1.\n# ══════════════════════════════════════════════════════════════════════════════\nVAULT_INSTALL = <<-\'VAULT_INSTALL_SHELL\'\n  set -e\n  export DEBIAN_FRONTEND=noninteractive\n  VAULT_PIN="2.2.1-1"\n  ACTUAL=$(dpkg-query -W -f=\'${Version}\' vault 2>/dev/null || true)\n  if [ "$ACTUAL" = "$VAULT_PIN" ]; then\n    apt-mark hold vault > /dev/null\n    echo "✅ Vault ${VAULT_PIN} ya instalado y fijado"; exit 0\n  fi\n  echo "📦 Instalando HashiCorp Vault ${VAULT_PIN} (instalado antes: ${ACTUAL:-ninguno})..."\n  if ! command -v wget > /dev/null || ! command -v gpg > /dev/null; then apt-get update -qq; apt-get install -y wget gnupg; fi\n  wget -O - https://apt.releases.hashicorp.com/gpg 2>/dev/null | \\\n    gpg --dearmor | \\\n    tee /usr/share/keyrings/hashicorp-archive-keyring.gpg > /dev/null\n  echo "deb [signed-by=/usr/share/keyrings/hashicorp-archive-keyring.gpg] https://apt.releases.hashicorp.com bookworm main" | \\\n    tee /etc/apt/sources.list.d/hashicorp.list\n  apt-get update -qq\n  apt-mark unhold vault > /dev/null 2>&1 || true\n  apt-get install -y --allow-downgrades "vault=${VAULT_PIN}"\n  apt-mark hold vault > /dev/null\n  GOT=$(dpkg-query -W -f=\'${Version}\' vault)\n  [ "$GOT" = "$VAULT_PIN" ] || { echo "❌ VAULT_INSTALL: instalado ${GOT}, se exige ${VAULT_PIN}"; exit 1; }\n  echo "✅ Vault $(vault version | head -1) instalado y fijado (apt-mark hold)"\nVAULT_INSTALL_SHELL\n', '# ══════════════════════════════════════════════════════════════════════════════\n# VAULT_INSTALL — [VAULT-INSTALL-D312] un único sitio donde se instala Vault (lo usan el defender y la VM etcd).\n# [TERCEROS-VAULT-D333] DEBT-LAB-TERCEROS-DESCARGA-SIN-VERIFICAR-001, lente Vault: todo en scripts/terceros/vault_instalar.sh,\n# con la versión exacta de provisioning/vault/VERSION y la clave del repositorio apt de HashiCorp comprobada por huella\n# (provisioning/vault/CLAVE, contrastada con la que publica HashiCorp). Antes: VAULT_PIN aquí y la clave bajada con wget\n# e instalada sin comprobar (HashiCorp la rotó el 10-sep-2026: se habría instalado cualquiera).\n# ══════════════════════════════════════════════════════════════════════════════\nVAULT_INSTALL = <<-\'VAULT_INSTALL_SHELL\'\n  bash /vagrant/scripts/terceros/vault_instalar.sh || { echo "❌ vault install failed"; exit 1; }\nVAULT_INSTALL_SHELL\n')],
    "Makefile": [('\t@$(EMECAS_PASO) test-onnxruntime-instalar -- $(MAKE) test-onnxruntime-instalar\n', '\t@$(EMECAS_PASO) test-onnxruntime-instalar -- $(MAKE) test-onnxruntime-instalar\n\t@$(EMECAS_PASO) test-vault-instalar -- $(MAKE) test-vault-instalar\n'), ('test-onnxruntime-instalar:\n\t@bash scripts/terceros/test_onnxruntime_instalar.sh\n', 'test-onnxruntime-instalar:\n\t@bash scripts/terceros/test_onnxruntime_instalar.sh\n\n# [TERCEROS-VAULT-D333] test-vault-instalar (Mac, sin VMs ni red): las funciones de scripts/terceros/vault_instalar.sh\n# (VERSION, versión del binario, anillo de antes de la rotación) y provisioning/vault/{VERSION,CLAVE}, también contra\n# funciones que lo aceptan todo.\n.PHONY: test-vault-instalar\ntest-vault-instalar:\n\t@bash scripts/terceros/test_vault_instalar.sh\n')],
}
NUEVOS = {
    'provisioning/vault/VERSION': '2.2.1-1\n',
    'provisioning/vault/CLAVE': '# provisioning/vault/CLAVE — [TERCEROS-VAULT-D333] huella de la clave con la que HashiCorp firma su repositorio apt\n# (https://apt.releases.hashicorp.com/gpg, "HashiCorp Security (HashiCorp Package Signing) <security+packaging@hashicorp.com>").\n# scripts/vigilancia/lib_apt_oficial.sh descarga la clave y SOLO la instala si todas sus claves principales están aquí.\n# Medida DAY333 en la descarga del mantenedor (una sola clave: creada el 9-sep-2026, caduca el 8-sep-2031) y CONTRASTADA\n# con la que publica HashiCorp en https://www.hashicorp.com/official-packaging-guide ("Current fingerprint"); con ella\n# verifica el InRelease de bookworm del 20-nov-2026. HashiCorp rotó la clave el 10-sep-2026: la anterior,\n# 798AEC654E5C15428C8E42EEAA16FCBCA621E701 (23-ene-2023 a 10-sep-2026), ya no firma el repositorio y no se acepta.\n# Si HashiCorp vuelve a rotarla, se cambia aquí (una por línea) tras contrastarla con esa página.\nD55C0D1AC78A8D8126CB631CFC9CA96ACA026560\n',
    'scripts/terceros/vault_instalar.sh': '#!/usr/bin/env bash\n# scripts/terceros/vault_instalar.sh — [TERCEROS-VAULT-D333] DEBT-LAB-TERCEROS-DESCARGA-SIN-VERIFICAR-001, lente Vault:\n# HashiCorp Vault desde el repositorio apt oficial de HashiCorp, con su clave comprobada por huella y la versión fijada.\n# Se ejecuta EN el defender y en la VM etcd (control-1), como root: aprovisionador vault-install del Vagrantfile\n# (VAULT_INSTALL, [VAULT-INSTALL-D312]: un único sitio donde se instala Vault). Lee de provisioning/vault/:\n#   VERSION  versión exacta del paquete deb, X.Y.Z-N (p. ej. 2.2.1-1). Sin defecto: mal o ausente, para (error de\n#            fabricante: el lab lo ve antes que nadie).\n#   CLAVE    huella de la clave de firma del repositorio (lib_apt_oficial.sh)\n# Antes (hasta DAY332): la versión en el Vagrantfile (VAULT_PIN) y la clave bajada con wget e instalada sin comprobar,\n# fuera la que fuera. HashiCorp la rotó el 10-sep-2026 (medido DAY333; ver provisioning/vault/CLAVE).\n# El repositorio se configura SIEMPRE, también si Vault ya está en su versión: una VM aprovisionada con la clave de\n# antes de la rotación pasa a la nueva, y se borra el anillo de antes (hashicorp-archive-keyring.gpg) si ya nadie lo usa.\n# Las funciones vault_* no tocan el sistema (las prueba scripts/terceros/test_vault_instalar.sh en el Mac).\nset -u\nLC_ALL=C; export LC_ALL\nlog() { echo "[TERCEROS-VAULT] $*"; }\nfallo() { echo "[TERCEROS-VAULT] FALLA: $*"; exit 1; }\n\n# vault_version_valida VERSION -> rc 0 si es X.Y.Z-N (la cadena entera: un salto de línea dentro también es error)\nvault_version_valida() {\n  [[ "$1" =~ ^[0-9]{1,3}[.][0-9]{1,3}[.][0-9]{1,3}-[0-9]{1,3}$ ]]\n}\n\n# vault_binario_cuadra VERSION LINEA -> rc 0 si la primera línea de `vault version` es de esa versión\n# (medido DAY332: "Vault v2.2.1 (0e7c41b936218bd2401ab0f891c93bec10e2e8e4), built 2026-10-22T16:27:49Z")\nvault_binario_cuadra() {\n  case "$2" in\n    "Vault v${1%-*} ("*) return 0 ;;\n  esac\n  return 1\n}\n\n# vault_anillo_huerfano ANILLO FICHERO... -> rc 0 si ninguno de los ficheros (los de apt) nombra el anillo\nvault_anillo_huerfano() {\n  local anillo=$1; shift\n  ! grep -qsF "$anillo" "$@"\n}\n\nmain() {\n  local src=${VAULT_SRC:-/vagrant/provisioning/vault} lib v actual linea\n  local viejo=/usr/share/keyrings/hashicorp-archive-keyring.gpg\n  lib=$(dirname "${BASH_SOURCE[0]}")/../vigilancia/lib_apt_oficial.sh\n  [ "$(id -u)" = 0 ] || fallo "hay que ejecutarlo como root"\n  for f in VERSION CLAVE; do [ -r "$src/$f" ] || fallo "no leo $src/$f"; done\n  v=$(tr -d \'[:space:]\' < "$src/VERSION")\n  vault_version_valida "$v" || fallo "$src/VERSION: \'$v\' mal formado (X.Y.Z-N: p. ej. 2.2.1-1). ERROR DE FABRICANTE: avisar a aRGus"\n  log "versión $v (de $src/VERSION)"\n  [ -r "$lib" ] || fallo "no leo $lib"\n  # shellcheck source=../vigilancia/lib_apt_oficial.sh\n  . "$lib"\n  repo_oficial hashicorp https://apt.releases.hashicorp.com/gpg "$src/CLAVE" \\\n    https://apt.releases.hashicorp.com "bookworm main" || fallo "repositorio de HashiCorp"\n  if [ -e "$viejo" ]; then\n    if vault_anillo_huerfano "$viejo" /etc/apt/sources.list /etc/apt/sources.list.d/*; then\n      rm -f "$viejo" && log "borrado $viejo (el anillo de antes de [TERCEROS-VAULT-D333]; ya no lo nombra apt)"\n    else\n      log "AVISO: $viejo sigue nombrado en la configuración de apt; no se borra"\n    fi\n  fi\n  actual=$(dpkg-query -W -f=\'${Version}\' vault 2>/dev/null || true)\n  if [ "$actual" = "$v" ]; then\n    apt-mark hold vault >/dev/null || fallo "apt-mark hold vault"\n    log "vault $v ya instalado"\n  else\n    log "instalando vault $v (instalado antes: ${actual:-ninguno})"\n    apt-get update -qq || fallo "apt-get update"\n    instalar_fijado vault "$v" || fallo "vault $v"\n  fi\n  linea=$(vault version 2>&1 | head -1)\n  vault_binario_cuadra "$v" "$linea" || fallo "el binario dice \'$linea\', se espera la versión ${v%-*}"\n  log "✅ $linea (paquete $v de provisioning/vault/VERSION, fijado con apt-mark hold)"\n}\n\nif [ "${BASH_SOURCE[0]}" = "$0" ]; then main "$@"; fi\n',
    'scripts/terceros/test_vault_instalar.sh': '#!/usr/bin/env bash\n# scripts/terceros/test_vault_instalar.sh — [TERCEROS-VAULT-D333] tests de las funciones vault_* de vault_instalar.sh y\n# de provisioning/vault/{VERSION,CLAVE} (Mac, sin VMs ni red: no tocan el sistema). Cada caso de rechazo se vuelve a\n# correr contra funciones que lo aceptan todo, y tiene que fallar ahí: así se ve que el test distingue.\nset -u\nLC_ALL=C; export LC_ALL\naqui=$(dirname "$0")\nsrc=${VAULT_SRC:-$aqui/../../provisioning/vault}\n. "$aqui/vault_instalar.sh"\n\nBIN=\'Vault v2.2.1 (0e7c41b936218bd2401ab0f891c93bec10e2e8e4), built 2026-10-22T16:27:49Z\'\nNUEVA=D55C0D1AC78A8D8126CB631CFC9CA96ACA026560\nVIEJA=798AEC654E5C15428C8E42EEAA16FCBCA621E701\nANILLO=/usr/share/keyrings/hashicorp-archive-keyring.gpg\ntmp=$(mktemp -d); trap \'rm -rf "$tmp"\' EXIT\nprintf \'deb [signed-by=/usr/share/keyrings/hashicorp.gpg] https://apt.releases.hashicorp.com bookworm main\\n\' > "$tmp/nueva.list"\nprintf \'deb [signed-by=%s] https://apt.releases.hashicorp.com bookworm main\\n\' "$ANILLO" > "$tmp/vieja.list"\ncasos=0; fallos=0; rechazos=0; rechazos_vistos=0\n\nacepta() { local n=$1; shift; casos=$((casos + 1)); if "$@" >/dev/null 2>&1; then echo "✅ $n"; else echo "❌ $n"; fallos=$((fallos + 1)); fi; }\nrechaza() { local n=$1; shift; casos=$((casos + 1)); rechazos=$((rechazos + 1)); if "$@" >/dev/null 2>&1; then echo "❌ $n"; fallos=$((fallos + 1)); rechazos_vistos=$((rechazos_vistos + 1)); else echo "✅ $n"; fi; }\n# huellas FICHERO -> las líneas sin comentar, como las lee lib_apt_oficial.sh\nhuellas() { grep -v \'^#\' "$1" | tr -d \' \\t\' | grep -E \'^[0-9A-F]{40}$\' | sort -u; }\nversion_repo() { vault_version_valida "$(tr -d \'[:space:]\' < "$src/VERSION")"; }\nclave_es() { [ "$(huellas "$src/CLAVE")" = "$1" ]; }\nclave_sin_basura() { [ "$(grep -v \'^#\' "$src/CLAVE" | grep -vc \'^[[:space:]]*$\')" = 1 ]; }\n\nlos_casos() {\n  acepta "versión 2.2.1-1 válida" vault_version_valida 2.2.1-1\n  acepta "versión 10.0.12-3 válida" vault_version_valida 10.0.12-3\n  rechaza "versión 2.2.1 (sin revisión del paquete)" vault_version_valida 2.2.1\n  rechaza "versión 2.2-1 (sin parche)" vault_version_valida 2.2-1\n  rechaza "versión v2.2.1-1 (con v)" vault_version_valida v2.2.1-1\n  rechaza "versión 2.2.1+ent-1 (enterprise)" vault_version_valida 2.2.1+ent-1\n  rechaza "versión vacía" vault_version_valida ""\n  rechaza "versión latest (por nombre)" vault_version_valida latest\n  rechaza "dos versiones en dos líneas" vault_version_valida $\'2.2.1-1\\n2.2.2-1\'\n  acepta "el binario medido DAY332 es 2.2.1-1" vault_binario_cuadra 2.2.1-1 "$BIN"\n  rechaza "el binario es otra versión (2.2.2)" vault_binario_cuadra 2.2.1-1 "${BIN/v2.2.1/v2.2.2}"\n  rechaza "el binario 2.2.10 no es 2.2.1" vault_binario_cuadra 2.2.1-1 "${BIN/v2.2.1/v2.2.10}"\n  rechaza "el binario enterprise 2.2.1+ent" vault_binario_cuadra 2.2.1-1 "${BIN/v2.2.1/v2.2.1+ent}"\n  rechaza "el binario no responde" vault_binario_cuadra 2.2.1-1 ""\n  rechaza "vault no está (bash: vault: command not found)" vault_binario_cuadra 2.2.1-1 "bash: vault: command not found"\n  acepta "anillo de antes huérfano: solo la lista nueva" vault_anillo_huerfano "$ANILLO" "$tmp/nueva.list"\n  acepta "anillo de antes huérfano: sin ficheros de apt" vault_anillo_huerfano "$ANILLO" "$tmp/no-existe.list"\n  rechaza "anillo de antes aún nombrado por una lista" vault_anillo_huerfano "$ANILLO" "$tmp/nueva.list" "$tmp/vieja.list"\n  acepta "provisioning/vault/VERSION bien formado" version_repo\n  acepta "provisioning/vault/CLAVE es la huella contrastada DAY333" clave_es "$NUEVA"\n  acepta "provisioning/vault/CLAVE: una sola línea sin comentar" clave_sin_basura\n  rechaza "provisioning/vault/CLAVE no es la clave de antes de la rotación" clave_es "$VIEJA"\n}\n\nlos_casos\necho "$((casos - fallos))/$casos casos"\ntotal=$fallos\n\n# Contra funciones que lo aceptan todo, cada rechazo tiene que dar ❌.\nvault_version_valida() { return 0; }\nvault_binario_cuadra() { return 0; }\nvault_anillo_huerfano() { return 0; }\nclave_es() { return 0; }\nesperados=$rechazos; casos=0; fallos=0; rechazos=0; rechazos_vistos=0\nlos_casos > /dev/null\nif [ "$rechazos_vistos" = "$esperados" ]; then\n  echo "✅ contra funciones que lo aceptan todo fallan los $esperados casos de rechazo"\nelse\n  echo "❌ contra funciones que lo aceptan todo fallan $rechazos_vistos de los $esperados casos de rechazo"; total=$((total + 1))\nfi\n[ "$total" = 0 ] && echo "✅ test-vault-instalar" || { echo "❌ test-vault-instalar: $total fallos"; exit 1; }\n',
}
EJECUTABLES = {"scripts/terceros/vault_instalar.sh", "scripts/terceros/test_vault_instalar.sh"}


def main():
    raiz = pathlib.Path.cwd()
    errores, salida = [], {}
    for nombre, sha in PARTIDA.items():
        b = (raiz / nombre).read_bytes()
        got = hashlib.sha256(b).hexdigest()
        if got != sha:
            errores.append(f"{nombre}: sha256 {got}, se espera {sha}")
            continue
        t = b.decode()
        for viejo, nuevo in CAMBIOS[nombre]:
            n = t.count(viejo)
            if n != 1:
                errores.append(f"{nombre}: ancla {viejo.splitlines()[0][:70]!r} aparece {n} veces, se espera 1")
                continue
            t = t.replace(viejo, nuevo, 1)
        salida[nombre] = t
    for p in NUEVOS:
        if (raiz / p).exists():
            errores.append(f"{p}: ya existe")
    if not (raiz / "scripts/vigilancia/lib_apt_oficial.sh").is_file():
        errores.append("scripts/vigilancia/lib_apt_oficial.sh: no está (vault_instalar.sh la usa)")
    if errores:
        print("❌ d333_vault_lente: no se escribe nada")
        for e in errores:
            print("   " + e)
        return 1
    for p, t in NUEVOS.items():
        f = raiz / p
        f.parent.mkdir(parents=True, exist_ok=True)
        f.write_text(t)
        if p in EJECUTABLES:
            os.chmod(f, 0o755)
    for nombre, t in salida.items():
        (raiz / nombre).write_text(t)
    for nombre in list(salida) + list(NUEVOS):
        print(f"✅ {nombre}  {hashlib.sha256((raiz / nombre).read_bytes()).hexdigest()}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
